INSERT INTO feature VALUES('joined-definitions','syntax','A signature joined with its value',NULL,'implemented','ordinary',NULL,'`def x : T = e ;` declares a name''s type and its value in one item, filed as the two halves a signature and a definition written apart file, so hover, outline and definition answer on it and a second signature or definition of the name is refused as a duplicate.','surface-grammar surface-lowering','corpus/model/basics/joined-definitions.gandr corpus/model/basics/joined-definitions-explicit.gandr','corpus/model/basics/joined-definitions.gandr',NULL);
